<?php
declare(strict_types=1);
/** Account-isolated applications; never mixed into the existing planner snapshot. */
final class LifeApplications {
 public const STAGES=['saved','preparing','applied','awaiting-feedback','interview','offer','rejected','withdrawn'];
 public function __construct(public LifeStore $store){$db=$store->db;if(!$db->inTransaction())$db->exec('CREATE TABLE IF NOT EXISTS life_applications (id INT PRIMARY KEY,version INT NOT NULL,state LONGTEXT NOT NULL,updated_at VARCHAR(30) NOT NULL)');}
 public function read():array{$q=$this->store->db->prepare('SELECT version,state FROM life_applications WHERE id=?');$q->execute([$this->store->tenantId]);$r=$q->fetch(PDO::FETCH_ASSOC);if(!$r){$state=['trackers'=>[],'categories'=>[],'opportunities'=>[],'documents'=>[],'events'=>[],'receipts'=>[]];try{$this->store->db->prepare('INSERT INTO life_applications VALUES (?,1,?,?)')->execute([$this->store->tenantId,json_encode($state),LifeStore::now()]);}catch(PDOException $e){$q->execute([$this->store->tenantId]);if(!$q->fetch())throw $e;}return $this->read();}return ['version'=>(int)$r['version'],'state'=>json_decode($r['state'],true,128,JSON_THROW_ON_ERROR)];}
 public static function id(mixed $value):string{if(!is_string($value)||!preg_match('/^[a-f0-9]{32}$/D',$value))throw new LifeError('This application record is unavailable.',404);return $value;}
 public static function find(array $s,string $collection,mixed $id,bool $active=false):array{$id=self::id($id);foreach($s[$collection]??[] as $r)if($r['id']===$id){if($active&&($r['archived']??false))throw new LifeError('Restore this record before using it.',409);return $r;}throw new LifeError('This application record is unavailable.',404);}
 public static function date(mixed $v):string{if($v==='')return '';if(!is_string($v)||!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$v)||!checkdate((int)substr($v,5,2),(int)substr($v,8,2),(int)substr($v,0,4)))throw new LifeError('Choose a valid date.');return $v;}
 public static function url(mixed $v):string{if($v==='')return '';if(!is_string($v)||strlen($v)>2000||!filter_var($v,FILTER_VALIDATE_URL))throw new LifeError('Use a public HTTPS link.');$u=parse_url($v);$host=strtolower($u['host']??'');if(($u['scheme']??'')!=='https'||isset($u['user'])||isset($u['pass'])||isset($u['port'])||$host==='localhost'||!str_contains($host,'.')||filter_var(trim($host,'[]'),FILTER_VALIDATE_IP)||preg_match('/\.(local|internal|localhost)$/D',$host))throw new LifeError('Use a public HTTPS link.');return $v;}
 public static function stages(mixed $v):array{if(!is_array($v)||count($v)<1||count($v)>20)throw new LifeError('Use 1–20 application stages.');$out=[];foreach($v as $stage){$key=$stage['id']??'';$label=LifeStore::text($stage['name']??'',60,true);if(!is_string($key)||!preg_match('/^[a-z][a-z0-9-]{0,39}$/D',$key)||!is_bool($stage['submitted']??null)||!is_bool($stage['successful']??null))throw new LifeError('Check the stage names and meanings.');$out[]=['id'=>$key,'name'=>$label,'submitted'=>$stage['submitted'],'successful'=>$stage['successful']];}if(count(array_unique(array_column($out,'id')))!==count($out))throw new LifeError('Stage names must be distinct.');return $out;}
 public static function defaults(string $kind):array{$labels=['saved'=>'Saved','preparing'=>'Preparing','applied'=>$kind==='education'?'Submitted':'Applied','awaiting-feedback'=>'Awaiting feedback','interview'=>$kind==='education'?'Assessment':'Interview / assessment','offer'=>$kind==='education'?'Accepted':'Offer / accepted','rejected'=>'Rejected','withdrawn'=>'Withdrawn'];$out=[];foreach($labels as $id=>$name)$out[]=['id'=>$id,'name'=>$name,'submitted'=>!in_array($id,['saved','preparing'],true),'successful'=>$id==='offer'];return $out;}
 private static function put(array &$s,string $c,array $record):void{foreach($s[$c] as $i=>$r)if($r['id']===$record['id']){$s[$c][$i]=$record;return;}$s[$c][]=$record;}
 public function mutate(int $version,string $operation,array $args,string $requestId=''):array{
  $this->read();$owns=!$this->store->db->inTransaction();if($owns)$this->store->db->beginTransaction();
  try{$r=$this->read();$s=$r['state'];$fingerprint=hash('sha256',json_encode([$operation,$args],JSON_THROW_ON_ERROR));if($requestId!==''){if(!preg_match('/^[a-zA-Z0-9_-]{8,100}$/D',$requestId))throw new LifeError('Invalid save request.');foreach($s['receipts'] as $receipt)if($receipt['requestId']===$requestId){if(!hash_equals($receipt['fingerprint'],$fingerprint))throw new LifeError('This request already saved a different change.',409);if($owns)$this->store->db->commit();return $r+['receipt'=>$receipt];}}
   if($r['version']!==$version)throw new LifeError('Applications changed in another tab. Reload before saving; your draft is preserved.',409);
   $id=$args['id']??'';$at=LifeStore::now();$collection=explode('.',$operation)[0];$collections=['tracker'=>'trackers','category'=>'categories','opportunity'=>'opportunities','document'=>'documents'];$c=$collections[$collection]??'';if($c==='')throw new LifeError('Unknown application action.',400);
   $old=$id!==''?self::find($s,$c,$id):null;$record=$old??['id'=>LifeStore::id(),'archived'=>false,'createdAt'=>$at];$record['updatedAt']=$at;$id=$record['id'];
   if(str_ends_with($operation,'.archive')||str_ends_with($operation,'.restore')){if(!$old)throw new LifeError('Choose an existing record.');$record['archived']=str_ends_with($operation,'.archive');if(!$record['archived']&&$c!=='trackers'){self::find($s,'trackers',$record['trackerId'],true);if($c==='opportunities'&&$record['categoryId']!=='')self::find($s,'categories',$record['categoryId'],true);}self::put($s,$c,$record);}
   elseif($operation==='opportunity.delete'){if(($args['confirmed']??false)!==true)throw new LifeError('Confirm permanent removal first.',403);if(!$old)throw new LifeError('Choose an existing opportunity.');$s['opportunities']=array_values(array_filter($s['opportunities'],fn($v)=>$v['id']!==$id));foreach($s['documents'] as &$d)if($d['opportunityId']===$id)$d['archived']=true;unset($d);$s['events']=array_values(array_filter($s['events'],fn($e)=>$e['recordId']!==$id));}
   elseif($operation==='tracker.save'){$kind=LifeStore::text($args['kind']??$old['kind']??'custom',60,true);$record['name']=LifeStore::text($args['name']??$old['name']??'',100,true);$record['kind']=$kind;$record['stages']=isset($args['stages'])?self::stages($args['stages']):($old['stages']??self::defaults($kind));foreach($s['opportunities'] as $o)if($o['trackerId']===$id&&!in_array($o['stage'],array_column($record['stages'],'id'),true))throw new LifeError('Keep stages that are used by opportunities.');if(!$old&&count($s['trackers'])>=30)throw new LifeError('Tracker limit reached.');self::put($s,$c,$record);}
   elseif($operation==='category.save'){$record['trackerId']=$args['trackerId']??$old['trackerId']??'';self::find($s,'trackers',$record['trackerId'],true);if($old&&$old['trackerId']!==$record['trackerId'])throw new LifeError('Create a category in the other tracker instead.');$record['name']=LifeStore::text($args['name']??$old['name']??'',100,true);if(!$old&&count($s['categories'])>=200)throw new LifeError('Category limit reached.');self::put($s,$c,$record);}
   elseif(in_array($operation,['opportunity.save','opportunity.applied'],true)){
    if($operation==='opportunity.applied'&&!$old)throw new LifeError('Save the opportunity first.');
    $record=array_merge(['categoryId'=>'','organisation'=>'','url'=>'','description'=>'','notes'=>'','location'=>'','cycle'=>'','openingDate'=>'','deadline'=>'','appliedDate'=>'','followUpDate'=>'','availability'=>'unknown','stage'=>'saved','checklist'=>[],'customFields'=>[],'taskIds'=>[],'goalId'=>''],$record);
    foreach(['title'=>200,'organisation'=>200,'description'=>20000,'notes'=>10000,'location'=>200,'cycle'=>100] as $field=>$max)$record[$field]=LifeStore::text($args[$field]??$record[$field]??'',$max,$field==='title');
    $record['trackerId']=$args['trackerId']??$record['trackerId']??'';$tracker=self::find($s,'trackers',$record['trackerId'],true);$record['categoryId']=$args['categoryId']??$record['categoryId'];if($record['categoryId']!==''){$cat=self::find($s,'categories',$record['categoryId'],true);if($cat['trackerId']!==$record['trackerId'])throw new LifeError('Choose a category in this tracker.');}
    foreach(['openingDate','deadline','appliedDate','followUpDate'] as $f)$record[$f]=self::date($args[$f]??$record[$f]);if($record['openingDate']&&$record['deadline']&&$record['openingDate']>$record['deadline'])throw new LifeError('The opening date must be before the deadline.');
    $record['url']=self::url($args['url']??$record['url']);$record['availability']=$args['availability']??$record['availability'];if(!in_array($record['availability'],['unknown','upcoming','open','closed'],true))throw new LifeError('Choose an opportunity availability.');
    $record['stage']=$args['stage']??$record['stage'];if($operation==='opportunity.applied'){$submitted=array_values(array_filter($tracker['stages'],fn($v)=>$v['submitted']&&!$v['successful']));if(!$submitted)throw new LifeError('Add a submitted stage to this tracker.');$record['stage']=$submitted[0]['id'];$record['appliedDate']=self::date($args['appliedDate']??(new DateTimeImmutable('now',new DateTimeZone(LifeStore::$timezone)))->format('Y-m-d'));}
    $stage=null;foreach($tracker['stages'] as $v)if($v['id']===$record['stage'])$stage=$v;if(!$stage)throw new LifeError('Choose a stage in this tracker.');if($stage['submitted']&&$record['appliedDate']==='')$record['appliedDate']=(new DateTimeImmutable('now',new DateTimeZone(LifeStore::$timezone)))->format('Y-m-d');
    if(array_key_exists('goalId',$args)){$record['goalId']=$args['goalId'];if($record['goalId']!=='')self::find(['goals'=>$this->store->read()['state']['goals']??[]],'goals',$record['goalId'],true);}
    if(isset($args['taskIds'])){if(!is_array($args['taskIds'])||count($args['taskIds'])>50)throw new LifeError('Choose up to 50 linked tasks.');foreach($args['taskIds'] as $taskId)self::find($this->store->read()['state'],'tasks',$taskId,true);$record['taskIds']=array_values(array_unique($args['taskIds']));}
    if(isset($args['checklist'])){if(!is_array($args['checklist'])||!array_is_list($args['checklist'])||count($args['checklist'])>100||array_filter($args['checklist'],fn($v)=>!is_array($v)))throw new LifeError('Use up to 100 checklist items.');$record['checklist']=array_map(fn($v)=>['text'=>LifeStore::text($v['text']??'',300,true),'done'=>($v['done']??false)===true],$args['checklist']);}
    if(isset($args['customFields'])){if(!is_array($args['customFields'])||!array_is_list($args['customFields'])||count($args['customFields'])>20||array_filter($args['customFields'],fn($v)=>!is_array($v)))throw new LifeError('Use up to 20 custom fields.');$record['customFields']=array_map(fn($v)=>['name'=>LifeStore::text($v['name']??'',80,true),'value'=>LifeStore::text($v['value']??'',1000)],$args['customFields']);}
    if(!$old&&count($s['opportunities'])>=5000)throw new LifeError('Opportunity limit reached.');self::put($s,$c,$record);
   }
   elseif($operation==='document.add'){if($old)throw new LifeError('Document originals cannot be overwritten. Save a new version.',403);
    $record['trackerId']=$args['trackerId']??'';self::find($s,'trackers',$record['trackerId'],true);$record['categoryId']=$args['categoryId']??'';$record['opportunityId']=$args['opportunityId']??'';
    foreach(['categoryId'=>'categories','opportunityId'=>'opportunities'] as $f=>$type)if($record[$f]!==''){$parent=self::find($s,$type,$record[$f],true);if($parent['trackerId']!==$record['trackerId'])throw new LifeError('Keep this document in its owning tracker.');if($f==='opportunityId'&&$record['categoryId']!==''&&$parent['categoryId']!==$record['categoryId'])throw new LifeError('Choose the opportunity’s category.');}
    foreach(['name'=>200,'mime'=>100,'kind'=>60,'fileId'=>32] as $f=>$max)$record[$f]=LifeStore::text($args[$f]??'',$max,true);self::id($record['fileId']);$record['size']=$args['size']??0;if(!is_int($record['size'])||$record['size']<1||$record['size']>5*1024*1024)throw new LifeError('Documents can be up to 5 MB.');$record['parentId']=$args['parentId']??'';$record['version']=1;if($record['parentId']!==''){$parent=self::find($s,'documents',$record['parentId'],true);if($parent['trackerId']!==$record['trackerId'])throw new LifeError('Use a base document in this tracker.');$record['version']=$parent['version']+1;}
    $record['preferred']=($args['preferred']??false)===true;$record['text']=LifeStore::text($args['text']??'',40000);if(count($s['documents'])>=500||array_sum(array_column($s['documents'],'size'))+$record['size']>100*1024*1024)throw new LifeError('Document bank storage limit reached.');
    if($record['preferred'])foreach($s['documents'] as &$d)if($d['trackerId']===$record['trackerId']&&$d['categoryId']===$record['categoryId']&&$d['opportunityId']===$record['opportunityId']&&$d['kind']===$record['kind'])$d['preferred']=false;unset($d);self::put($s,$c,$record);
   }
   elseif($operation==='document.prefer'){if(!$old)throw new LifeError('Choose a document.');foreach($s['documents'] as &$d)if($d['trackerId']===$old['trackerId']&&$d['categoryId']===$old['categoryId']&&$d['opportunityId']===$old['opportunityId']&&$d['kind']===$old['kind'])$d['preferred']=$d['id']===$id;unset($d);}
   else throw new LifeError('Unknown application action.',400);
   if($operation!=='opportunity.delete')$s['events'][]=['id'=>LifeStore::id(),'recordId'=>$id,'operation'=>$operation,'at'=>$at,'stage'=>$record['stage']??null,'previousStage'=>$old['stage']??null];$s['events']=array_slice($s['events'],-10000);
   $receipt=['id'=>LifeStore::id(),'requestId'=>$requestId,'fingerprint'=>$fingerprint,'recordId'=>$id,'operation'=>$operation,'version'=>$version+1,'summary'=>($operation==='opportunity.applied'?'Marked as applied: ':($operation==='opportunity.delete'?'Permanently removed: ':'Saved: ')).($record['title']??$record['name']??'application record')];if($requestId!==''){$s['receipts'][]=$receipt;$s['receipts']=array_slice($s['receipts'],-500);}
   $q=$this->store->db->prepare('UPDATE life_applications SET version=version+1,state=?,updated_at=? WHERE id=? AND version=?');$q->execute([json_encode($s,JSON_THROW_ON_ERROR),$at,$this->store->tenantId,$version]);if($q->rowCount()!==1)throw new LifeError('Applications changed while saving. Reload before retrying.',409);if($owns)$this->store->db->commit();$saved=$this->read();if($saved['version']!==$version+1)throw new LifeError('The application save could not be verified.',409);return $saved+['receipt'=>$receipt];
  }catch(Throwable $e){if($owns&&$this->store->db->inTransaction())$this->store->db->rollBack();throw $e;}
 }
 public function index(string $query='',array $screen=[]):array{$state=$this->read()['state'];$out=[];$words=array_filter(preg_split('/[^\pL\pN]+/u',mb_strtolower($query)),fn($w)=>mb_strlen($w)>2);foreach(['trackers','categories','opportunities'] as $kind){$rows=$state[$kind];if($kind==='opportunities'){usort($rows,function($a,$b)use($words,$screen){$score=fn($r)=>(($screen['opportunityId']??'')===$r['id']?1000:0)+array_sum(array_map(fn($w)=>mb_stripos(($r['title']??'').' '.($r['organisation']??''),$w)!==false?10:0,$words));return $score($b)<=>$score($a);});}$out[$kind]=array_map(fn($v)=>array_intersect_key($v,array_flip(['id','name','title','kind','organisation','trackerId','categoryId','stage','stages','availability','deadline','openingDate','appliedDate','archived'])),array_slice($rows,0,100));$out['counts'][$kind]=count($rows);}return $out;}

 public static function voiceTargets(array $s,array $actions,string $request,array $screen):void{$said=' '.LifeVoiceProtocol::normalized($request).' ';foreach($actions as $action){if(!preg_match('/^(opportunity|category)\./',$action['operation']))continue;$args=$action['arguments'];foreach(['trackerId'=>'trackers','categoryId'=>'categories'] as $field=>$collection){if(empty($args[$field]))continue;$record=self::find($s,$collection,$args[$field],true);if(($screen[$field]??'')===$record['id'])continue;$active=array_values(array_filter($s[$collection],fn($v)=>!$v['archived']));if($field==='trackerId'&&count($active)===1)continue;$name=LifeVoiceProtocol::normalized($record['name']);if(!str_contains($said,' '.$name.' '))throw new LifeError('Please clarify the destination tracker or category.');$same=array_filter($active,fn($v)=>LifeVoiceProtocol::normalized($v['name'])===$name);if(count($same)>1)throw new LifeError('More than one destination has that name. Please select the tracker or category first.');}}}
 public static function visible(array $s):array{$trackers=array_column(array_filter($s['trackers'],fn($v)=>!$v['archived']),'id');$cats=array_column(array_filter($s['categories'],fn($v)=>!$v['archived']),'id');return array_values(array_filter($s['opportunities'],fn($v)=>!$v['archived']&&in_array($v['trackerId'],$trackers,true)&&($v['categoryId']===''||in_array($v['categoryId'],$cats,true))));}
 public static function statistics(array $s):array{$rows=self::visible($s);$applied=0;$waiting=0;$successful=0;foreach($rows as $r){$tracker=self::find($s,'trackers',$r['trackerId']);foreach($tracker['stages'] as $stage)if($stage['id']===$r['stage']){$applied+=(int)($r['appliedDate']!=='');$successful+=(int)$stage['successful'];$waiting+=(int)($stage['submitted']&&!$stage['successful']&&!in_array($stage['id'],['rejected','withdrawn'],true));}}return ['saved'=>count($rows),'applied'=>$applied,'waiting'=>$waiting,'successful'=>$successful];}
}
